import React, { useState, useEffect } from 'react';
import { Sun, Moon, Palette, Home, Info, Settings, User } from 'lucide-react';

const Header = ({ darkMode, toggleDarkMode }) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [colorPaletteOpen, setColorPaletteOpen] = useState(false);


  // Navigation items
  const navItems = [
    { name: 'Accueil', icon: <Home size={18} />, href: '#' },
    { name: 'À propos', icon: <Info size={18} />, href: '#' },
    { name: 'Profil', icon: <User size={18} />, href: '#' },
    { name: 'Paramètres', icon: <Settings size={18} />, href: '#' },
  ];

  return (
    <header className="sticky top-0 z-50 w-full border-b border-neutral-200 dark:border-neutral-800 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-md">
      <div className="container mx-auto px-4 py-3">
        <div className="flex items-center justify-between">
          {/* Logo */}
          <div className="flex items-center space-x-2">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center">
              <span className="text-white font-bold">R</span>
            </div>
            <h1 className="text-xl font-bold text-neutral-900 dark:text-white">
              React<span className="text-primary-600 dark:text-primary-400">UI</span>
            </h1>
          </div>

          {/* Navigation Desktop */}
          <nav className="hidden md:flex items-center space-x-1">
            {navItems.map((item) => (
              <a
                key={item.name}
                href={item.href}
                className="flex items-center space-x-1 px-4 py-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:text-primary-600 dark:hover:text-primary-400 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors duration-200"
              >
                {item.icon}
                <span>{item.name}</span>
              </a>
            ))}
          </nav>

          {/* Actions */}
          <div className="flex items-center space-x-2">
            {/* Sélecteur de palette de couleurs */}
            <div className="relative">
              <button
                onClick={() => setColorPaletteOpen(!colorPaletteOpen)}
                className="p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors duration-200"
                aria-label="Changer la palette de couleurs"
              >
                <Palette size={20} />
              </button>

              {colorPaletteOpen && (
                <>
                  <div 
                    className="fixed inset-0 z-40" 
                    onClick={() => setColorPaletteOpen(false)}
                  />
                  <div className="absolute right-0 mt-2 w-64 p-4 bg-white dark:bg-neutral-800 rounded-xl shadow-xl border border-neutral-200 dark:border-neutral-700 z-50 animate-fade-in">
                    <h3 className="text-sm font-semibold text-neutral-900 dark:text-white mb-3">
                      Palettes de couleurs
                    </h3>
                    <div className="space-y-2">
                      {colorPalettes.map((palette) => (
                        <button
                          key={palette.name}
                          className="flex items-center justify-between w-full p-3 rounded-lg hover:bg-neutral-100 dark:hover:bg-neutral-700 transition-colors duration-200"
                          onClick={() => {
                            // Dans une application réelle, vous changeriez la palette ici
                            console.log('Changement de palette:', palette.name);
                            setColorPaletteOpen(false);
                          }}
                        >
                          <span className="text-neutral-700 dark:text-neutral-300">{palette.name}</span>
                          <div className="flex space-x-1">
                            <div 
                              className="w-6 h-6 rounded-full border border-neutral-300 dark:border-neutral-600"
                              style={{ backgroundColor: palette.primary }}
                            />
                            <div 
                              className="w-6 h-6 rounded-full border border-neutral-300 dark:border-neutral-600"
                              style={{ backgroundColor: palette.secondary }}
                            />
                            <div 
                              className="w-6 h-6 rounded-full border border-neutral-300 dark:border-neutral-600"
                              style={{ backgroundColor: palette.accent }}
                            />
                          </div>
                        </button>
                      ))}
                    </div>
                  </div>
                </>
              )}
            </div>

            {/* Toggle mode sombre/clair */}
            <button
              onClick={toggleDarkMode}
              className="p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors duration-200"
              aria-label={darkMode ? 'Activer le mode clair' : 'Activer le mode sombre'}
            >
              {darkMode ? <Sun size={20} /> : <Moon size={20} />}
            </button>

            {/* Bouton menu mobile */}
            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="md:hidden p-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors duration-200"
              aria-label="Menu"
            >
              <div className="space-y-1">
                <div className={`w-6 h-0.5 bg-current transition-transform duration-300 ${mobileMenuOpen ? 'rotate-45 translate-y-1.5' : ''}`} />
                <div className={`w-6 h-0.5 bg-current transition-opacity duration-300 ${mobileMenuOpen ? 'opacity-0' : 'opacity-100'}`} />
                <div className={`w-6 h-0.5 bg-current transition-transform duration-300 ${mobileMenuOpen ? '-rotate-45 -translate-y-1.5' : ''}`} />
              </div>
            </button>
          </div>
        </div>

        {/* Menu mobile */}
        {mobileMenuOpen && (
          <div className="mt-4 md:hidden animate-slide-up">
            <div className="py-2 border-t border-neutral-200 dark:border-neutral-800">
              {navItems.map((item) => (
                <a
                  key={item.name}
                  href={item.href}
                  className="flex items-center space-x-3 px-4 py-3 rounded-lg text-neutral-700 dark:text-neutral-300 hover:text-primary-600 dark:hover:text-primary-400 hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors duration-200"
                  onClick={() => setMobileMenuOpen(false)}
                >
                  {item.icon}
                  <span>{item.name}</span>
                </a>
              ))}
            </div>
          </div>
        )}
      </div>
    </header>
  );
};

export default Header;
